// Period of the odd-term rule for V(2,n) with E = {2, 2n, 2n^2+2}: b[j] (u = 2j+1) = [b[j-1] + b[j-n] + b[j-(n^2+1)] == 1]
// State: last W = n^2+1 bits, stored as a bitset. Initial state taken from the actual sequence (generated by verify2's rule) at u0.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#define MAXW 8192
typedef struct { uint64_t w[MAXW/64]; } St;
int W, d1, d2, d3, NW;
static inline int getb(const St*s,int i){ return (s->w[i>>6]>>(i&63))&1; }
// bit i = b[j-1-i]
static inline void step(St*s){ int nb = (getb(s,d1-1)+getb(s,d2-1)+getb(s,d3-1))==1;
  // shift left by 1 (towards higher index), insert nb at bit 0
  for(int k=NW-1;k>0;k--) s->w[k]=(s->w[k]<<1)|(s->w[k-1]>>63);
  s->w[0]=(s->w[0]<<1)|nb; int top=W&63; if(top) s->w[NW-1]&=(1ULL<<top)-1; }
int eq(const St*a,const St*b){ return memcmp(a->w,b->w,NW*8)==0; }
int main(int c,char**v){ long n=atol(v[1]); long L=atol(v[2]); long maxsteps=atol(v[3]);
  // generate actual sequence up to L (greedy, as in verify2)
  char *in=calloc(L+1,1); long ev[64],ne=0; long *od=malloc(sizeof(long)*(L/2+2)),no=0;
  in[2]=1; ev[ne++]=2; in[n]=1; od[no++]=n;
  for(long m=n+1;m<=L;m++){ int r=0;
    if(m&1){ for(long i=0;i<ne&&r<2;i++){long b=m-ev[i]; if(b>0&&in[b]) r++;} }
    else { for(long i=0;i<ne&&r<2;i++) for(long j=i;j<ne&&r<2;j++) if(ev[i]+ev[j]==m) r++;
           for(long i=0;i<no&&r<2&&2*od[i]<=m;i++) if(in[m-od[i]]) r++; }
    if(r==1){ in[m]=1; if(m&1) od[no++]=m; else { ev[ne++]=m; if(ne>3){ printf("extra even %ld\n",m); return 1;} } } }
  W=n*n+1; d1=1; d2=n; d3=n*n+1; NW=(W+63)/64;
  long u0=2*n*n+3; // first odd above maxE
  St s; memset(&s,0,sizeof s);
  for(int i=0;i<W;i++){ long u=u0-2*(i+1); if(u>0 && in[u]) s.w[i>>6]|=1ULL<<(i&63); }
  // sanity: simulate vs data
  St t=s; long mism=0; for(long u=u0; u<=L; u+=2){ step(&t); if(((t.w[0])&1)!=in[u]) mism++; }
  printf("n=%ld W=%d: rule simulation vs data mismatches up to %ld: %ld\n",n,W,L,mism);
  // Brent
  St tort=s, hare=s; step(&hare); long power=1, lam=1, steps=0;
  while(!eq(&tort,&hare)){ if(power==lam){ tort=hare; power*=2; lam=0; } step(&hare); lam++; if(++steps>maxsteps){ printf("no cycle within %ld steps\n",maxsteps); return 1; } }
  tort=s; hare=s; for(long i=0;i<lam;i++) step(&hare); long mu=0; while(!eq(&tort,&hare)){ step(&tort); step(&hare); mu++; }
  printf("n=%ld: period %ld odd steps (= %ld integers), preperiod %ld steps (periodic from u = %ld)\n",n,lam,2*lam,mu,u0+2*mu);
}
